operations.insert:
varying vec3 vertColour;
varying vec3 vertNormal;
varying vec2 texCoords;
varying vec3 meLensMeshPos;
varying vec3 meLensMeshNormal;
varying vec3 meLensBodyViewRay;
uniform mat4 MELensToBody;
uniform vec4 MELensWheelArch;

// Procedural Vehicles_Wheel: tangent at2, native UV at3.
layout (location = 3) in vec2 meLensProceduralUv;
uniform float MELensWheelUV;

if (MELensWheelUV > 0.5) texCoords = meLensProceduralUv;
meLensMeshPos = vertex.xyz;
meLensBodyViewRay = vec3(0.0, 0.0, -1.0);
if (MELensWheelArch.x > 0.5) {
	vec4 clipRay = inverse(ModelViewProjection * transform) * vec4(0.0, 0.0, -1.0, 0.0);
	meLensBodyViewRay = (MELensToBody * vec4(clipRay.xyz, 0.0)).xyz;
}

meLensMeshNormal = normal.xyz;
